/* Structure-specific teaching annotations. Source records are displayed alongside each entry. */
(() => {
'use strict';
const os='https://openstax.org/books/anatomy-and-physiology-2e/pages/';
const book=(title,url)=>({title,url});
const R={
 heart:book('OpenStax · Heart anatomy',os+'19-1-heart-anatomy'),cycle:book('Pollock & Makaryus · Physiology of the cardiac cycle','https://www.ncbi.nlm.nih.gov/books/NBK459327/'),
 valves:book('University of Minnesota · Cardiac valve nomenclature','https://www.vhlab.umn.edu/atlas/anatomy-tutorial/cardiac-valve-nomenclature.shtml'),
 electric:book('OpenStax · Cardiac muscle and electrical activity',os+'19-2-cardiac-muscle-and-electrical-activity'),
 coron:book('NCBI Bookshelf · Physiology of the coronary circulation','https://www.ncbi.nlm.nih.gov/books/NBK482413/'),
 cv:book('Cardiac venous system mapping · Heart Rhythm','https://pmc.ncbi.nlm.nih.gov/articles/PMC11993788/'),
 vessel:book('OpenStax · Circulatory pathways',os+'20-5-circulatory-pathways'),pressure:book('OpenStax · Blood flow, pressure, and resistance',os+'20-2-blood-flow-blood-pressure-and-resistance'),
 lung:book('Kandathil & Chamarthy · Pulmonary vascular anatomy and variants','https://cdt.amegroups.org/article/view/19060/html'),
 pulmonary:book('European Respiratory Journal · Right ventricular and pulmonary vascular physiology','https://doi.org/10.1183/13993003.01900-2018'),
 pven:book('Polaczek et al. · Pulmonary venous variants on computed tomography','https://jtd.amegroups.org/article/view/36486/html'),
 cerebral:book('Cipolla · Cerebral circulation, anatomy and collateral pathways','https://www.ncbi.nlm.nih.gov/books/NBK53086/'),
 brainvein:book('Hufnagle & Tadi · Brain veins','https://www.ncbi.nlm.nih.gov/books/NBK546605/'),
 systemic:book('Chan & Chi · Extremity venous anatomy','https://www.ncbi.nlm.nih.gov/books/NBK27355/'),
 azygos:book('Donohue & Daly · Azygos veins','https://www.ncbi.nlm.nih.gov/books/NBK554430/'),
 liver:book('Lautt · Hepatic arterial buffer response','https://www.ncbi.nlm.nih.gov/books/NBK53066/'),
 kidney:book('OpenStax · Regulation of renal blood flow',os+'25-7-regulation-of-renal-blood-flow'),
};
window.circulationSources=R;
const C={};
function card(id,physiology,relationship,refs,variation=''){
 const e=heartStructures.find(x=>x.id===id);
 C[id]={course:e?.location||'',physiology,relationship,variation,sources:refs.split(' ').map(k=>R[k])};
}
card('heart','The two ventricles act in series. Right ventricular output becomes pulmonary venous return to the left heart. Over time the two outputs match. A sustained imbalance changes the volume stored in the pulmonary or systemic circulation.','Chamber filling depends on relaxation and the upstream pressure gradient. Activation of the conduction system coordinates ejection, while valve motion follows pressure differences.','heart cycle electric');
card('right-atrium','During ventricular systole, the right atrium stores incoming systemic venous blood. Once the tricuspid valve opens, the atrium acts as a conduit. Late atrial contraction adds to ventricular filling.','It receives the superior and inferior venae cavae, coronary sinus, and direct cardiac venous tributaries. A rise in right atrial pressure reduces the gradient for systemic venous return if upstream pressure is fixed.','heart cycle cv');
card('right-ventricle','The right ventricle generates pulsatile flow through the low-resistance pulmonary circulation. Increased pulmonary resistance raises the pressure it must generate, while reduced pulmonary arterial compliance also increases pulsatile load.','The tricuspid inlet and pulmonary outlet are distinct. The smooth subpulmonary infundibulum leads to the pulmonary valve. Contraction and relaxation involve the free wall and the shared septum.','heart cycle pulmonary');
card('left-atrium','Pulmonary venous blood fills the left atrium during ventricular systole. In diastole its conduit and late booster-pump functions help fill the left ventricle. Reduced ventricular compliance can elevate atrial and upstream pulmonary venous pressure.','Pulmonary venous ostia enter the posterior atrium. The mitral orifice is its outlet. Pressure in the atrium varies during the cardiac cycle even while pulmonary venous inflow continues.','heart cycle pven','A common left pulmonary venous ostium or an additional right-sided vein can change the number of atrial openings.');
card('left-ventricle','During isovolumetric contraction, pressure rises with both left-sided valves closed. Forward ejection begins when ventricular pressure exceeds aortic pressure. In early relaxation, pressure falls at nearly fixed end-systolic volume until the mitral valve opens.','Stroke volume equals end-diastolic volume minus end-systolic volume. The chamber’s wall thickness supports systemic pressure generation. Filling depends on relaxation and ventricular compliance.','heart cycle');
card('tricuspid-valve','When right atrial pressure exceeds right ventricular pressure in diastole, the leaflets open. Reversal of this gradient closes them at the onset of systole. Coaptation limits return of blood to the right atrium.','The annulus, leaflets, chordae, papillary muscles, and adjacent ventricular myocardium function together. The septal attachment lies closer to the apex than the mitral insertion.','valves heart cycle','The familiar anterior, posterior, and septal pattern is a naming convention. Scallops and accessory leaflets vary.');
card('mitral-valve','Diastolic flow depends on the pressure difference between the left atrium and ventricle and the available orifice area. During systole, leaflet coaptation maintains separation between high ventricular and lower atrial pressures.','Anterior and posterior leaflets attach to the annulus. Chordae from both papillary groups support both leaflets. The anterior leaflet is adjacent to the left ventricular outflow tract.','valves cycle');
card('aortic-valve','The valve opens as left ventricular pressure overtakes aortic pressure. When ejection ends and aortic pressure becomes greater, a brief tendency to reverse flow fills the cusps and closes the valve.','The sinuses lie just beyond the cusps. The usual coronary ostia lie in the right and left aortic sinuses. The valve has no chordae or papillary muscles.','valves cycle coron','The reference depicts tricuspid aortic anatomy. A bicuspid aortic valve is a recognized congenital configuration.');
card('pulmonary-valve','The pulmonary valve permits systolic flow from the infundibulum to the pulmonary trunk and closes when the pressure gradient reverses. The right-sided event need not coincide exactly with aortic closure.','Its semilunar cusps operate without chordae. The pulmonary root lies anterior and to the left of the aortic root.','valves cycle pulmonary');
card('aorta','The ascending aorta receives the stroke volume during systole. Elastic expansion stores part of that energy. Recoil supports forward flow and arterial pressure after the aortic valve closes.','The coronary ostia arise near the root. Arch branches supply the head, neck and upper limbs. The descending aorta continues to the thorax and abdomen.','heart vessel pressure','Arch branching varies. The usual three-branch arrangement is shown in the teaching model.');
card('pulmonary-trunk','The trunk transmits right ventricular stroke volume into both lungs. Its elastic walls and those of the proximal pulmonary arteries buffer pressure pulsatility before blood reaches smaller arteries and capillaries.','Blood is relatively oxygen-poor at this point. Pulmonary vascular resistance reflects the mean transpulmonary pressure gradient divided by cardiac output. Compliance contributes to right ventricular load as well.','lung pulmonary');
for(const side of ['right','left'])card(side+'-pulmonary-artery','This branch delivers mixed venous blood to the '+side+' lung. Regional perfusion depends on downstream vascular resistance, alveolar pressure and lung volume. Locally low alveolar oxygen can increase arteriolar tone.','The '+(side==='right'?'right branch crosses posterior to the ascending aorta and superior vena cava.':'left branch passes under the aortic arch and superior to the left main bronchus.')+' Lobar and segmental branches distribute flow alongside the airway tree.','lung pulmonary');
card('pulmonary-veins','Pulmonary venous inflow is phasic as atrial pressure and ventricular motion change through the beat. These vessels carry the blood that has passed through ventilated and perfused alveolar capillary beds.','Pulmonary venules converge toward the hilum and then the left atrium. Many larger venous tributaries run between segments, while arteries generally accompany segmental bronchi.','pven lung','A common left ostium and accessory veins, including separate middle-lobe drainage, are documented variants.');
card('superior-vena-cava','Inflow from the upper body reaches the right atrium through a low-pressure conduit. The gradient changes with right atrial pressure and the respiratory cycle.','The right and left brachiocephalic veins form the superior vena cava. The azygos usually joins just before it enters the pericardium.','heart azygos');
card('inferior-vena-cava','The inferior vena cava returns systemic venous blood from below the diaphragm. Changes in abdominal and intrathoracic pressures affect flow to the right atrium, and the compliant vein changes caliber with its transmural pressure.','The hepatic veins join near the diaphragm. Portal blood reaches the caval system after passage through liver sinusoids and hepatic veins.','heart vessel');
card('brachiocephalic-trunk','This conduit delivers part of each aortic pulse to the right common carotid and right subclavian arteries. Local demand and downstream resistance govern how much of that flow enters each territory.','It is usually the first arch branch. Its two main daughters separate the head-and-neck route from the upper-limb route.','vessel pressure','The left common carotid can share an origin with the brachiocephalic trunk.');
card('left-common-carotid','Flow divides between internal and external carotid territories. Near the bifurcation, stretch receptors in the carotid sinus contribute to short-term blood pressure regulation.','The left common carotid typically originates from the arch, unlike the right common carotid, which usually comes from the brachiocephalic trunk.','vessel cerebral');
card('left-subclavian','Flow serves the upper limb and proximal branches, including the vertebral circulation. Arm exercise lowers resistance in active muscle, increasing limb flow for a given perfusion pressure.','Usually the last of three aortic arch branches, it passes over the first rib and becomes the axillary artery at its lateral border.','vessel pressure');
card('left-coronary-artery','The left main coronary artery distributes inflow to the LAD and circumflex territories. Coronary flow increases chiefly through downstream resistance changes as oxygen demand rises. Left ventricular intramyocardial compression makes perfusion strongly phasic.','Its origin lies in the left aortic sinus. The short trunk courses between the pulmonary trunk and the left atrial appendage.','heart coron','A ramus intermedius can accompany the LAD and circumflex at a trifurcation.');
card('left-anterior-descending','Diagonal and septal branches deliver oxygen to the anterior left ventricular wall and anterior septum. The deeper subendocardium experiences the greatest systolic compression, making diastolic perfusion especially important.','The LAD follows the anterior interventricular groove near the great cardiac vein. Septal perforators penetrate inward while diagonal branches run across the anterolateral surface.','heart coron cv','The length of the LAD and how far it wraps around the apex vary.');
card('circumflex-artery','This vessel supplies the lateral left ventricular wall through obtuse marginal branches. In a left-dominant circulation it also gives rise to the posterior interventricular artery, enlarging its perfusion territory.','The circumflex follows the left atrioventricular groove near the great cardiac vein and coronary sinus.','heart coron cv','Dominance describes the origin of the posterior interventricular artery and can change the posterior supply territory.');
card('right-coronary-artery','The right coronary artery supplies right ventricular myocardium and, in many hearts, inferior left ventricular and nodal territories. Right ventricular perfusion commonly continues during systole because compression is lower than in the left ventricular wall.','It courses from the right aortic sinus into the right atrioventricular groove and gives off marginal branches. In a right-dominant pattern it reaches the crux and gives off the posterior interventricular artery.','heart coron','Nodal branch origins and the extent of the inferior territory vary.');
card('right-marginal-artery','The acute marginal branch supplies the free wall of the right ventricle. Flow responds to oxygen use in the downstream myocardium as the right heart changes its workload.','It leaves the right coronary artery and follows the acute margin toward the apex.','heart coron');
card('posterior-interventricular-artery','Septal and ventricular branches perfuse the inferior ventricular walls and the posterior part of the septum. Its perfusion territory helps define how coronary dominance changes vulnerability to an upstream obstruction.','It shares the posterior interventricular groove with the middle cardiac vein. The teaching model shows its origin from the right coronary artery.','heart coron cv','In left dominance, its origin is the circumflex artery.');
card('great-cardiac-vein','Venous blood from much of the anterior and lateral left ventricular myocardium returns to the coronary sinus through this route. This outflow reflects upstream capillary exchange and phasic myocardial compression.','It ascends with the LAD then turns into the left atrioventricular groove near the circumflex artery.','cv coron');
card('middle-cardiac-vein','This vein collects blood from posterior interventricular and adjacent myocardial territories and delivers it to the coronary sinus near its right atrial end.','It ascends in the posterior interventricular groove near the posterior interventricular artery.','cv coron');
card('small-cardiac-vein','Blood from parts of the right heart can return along the acute margin to the coronary sinus. Other right ventricular venous blood reaches the atrium directly through anterior cardiac veins.','It follows the right cardiac margin and right atrioventricular groove, close to right coronary branches.','cv','The caliber, terminal drainage, and even presence of the small cardiac vein vary.');
card('anterior-cardiac-veins','These veins drain the anterior right ventricular wall directly into the right atrium. Their outflow bypasses the coronary sinus.','They cross the right atrioventricular groove near branches of the right coronary artery.','cv','The number and entry sites of these small veins vary.');
card('coronary-sinus','Several myocardial venous territories converge here before entering the right atrium. Coronary sinus blood therefore reflects venous effluent from a large, incomplete portion of myocardial perfusion.','The sinus runs posteriorly in the atrioventricular groove. Its ostium lies in the right atrium near the inferior vena cava and septal tricuspid region.','cv heart','Direct cardiac veins and the smallest cardiac veins provide additional drainage outside the sinus.');
card('interventricular-septum','The muscular septum contributes to pressure generation in both ventricles. A shared septum couples chamber geometry, so pressure or volume loading on one side can alter filling on the other.','The septum has muscular and membranous portions. Bundle branches travel on its ventricular aspects.','heart electric pulmonary');
card('papillary-muscles','Papillary muscles develop tension with ventricular systole and restrain leaflet eversion through the chordae. The ventricular–atrial pressure gradient brings the leaflets together.','Left ventricular papillary groups support both mitral leaflets. Right ventricular papillary attachments support the tricuspid apparatus.','valves heart cycle','The number of papillary heads and the arrangement of their chordae vary.');
card('chordae-tendineae','These collagenous cords transmit papillary muscle tension to atrioventricular valve leaflets during systole. Normal tethering allows leaflet coaptation while limiting displacement into the atria.','Chordae link leaflets to ventricular papillary muscles. Neither semilunar valve requires this apparatus.','valves heart');
card('sinoatrial-node','Spontaneous diastolic depolarization permits this tissue to initiate sinus rhythm. Autonomic input changes the rate at which pacemaker cells reach threshold. The atria depolarize before ventricular activation.','The node lies subepicardially near the superior caval–right atrial junction. Surface ECG records atrial depolarization as the P wave.','heart electric');
card('atrioventricular-node','Slow conduction through the atrioventricular junction allows time for atrial contribution to ventricular filling. Nodal conduction properties also influence how many atrial impulses reach the ventricles.','The compact node lies close to the apex of the triangle of Koch in the right atrium. The His bundle continues across the insulating fibrous skeleton.','heart electric');
card('atrioventricular-bundle','The His bundle conducts the impulse from the atrioventricular node toward the bundle branches. In a normal heart this axis provides the electrical connection across the atrioventricular insulating plane.','It traverses the fibrous skeleton near the membranous septum, then continues toward the right and left ventricular conduction systems.','heart electric');
card('purkinje-fibers','Rapid conduction through the subendocardial network coordinates ventricular depolarization. Mechanical contraction follows electrical activation after excitation–contraction coupling.','The network connects the bundle branches with ventricular myocardium. On a surface ECG the QRS complex reflects ventricular depolarization.','heart electric');
window.cardiacDossiers=C;
/* Shared microvascular mechanisms are explicit and kept separate from each vessel’s territory. */
const families={
 pump:['Paired circuits','Left ventricular output enters the systemic arteries and returns through the systemic veins. The same flow then traverses the pulmonary circulation over time. Tissue perfusion depends on the local arteriovenous pressure difference and resistance.','The arterial and venous sides communicate through tissue microcirculation. Venous return supplies ventricular preload.','vessel pressure'],
 aorta:['Elastic conduit','Elastic expansion during systole and recoil during diastole smooth out the pulsatile output of the left ventricle. Downstream arterioles regulate regional resistance.','Branches originate at different levels of the aorta and serve separate parallel tissue beds.','vessel pressure'],
 cerebral:['Cerebral perfusion','Cerebral resistance vessels adjust caliber in response to perfusion pressure and local metabolic signals. Cortical connections may redistribute flow between territories, while deep perforating territories often have limited alternative supply.','The anatomic pattern and caliber of communicating vessels determine how much collateral flow can develop.','cerebral vessel'],
 brainvein:['Cerebral venous return','Pressure differences drain cerebral venous blood through valveless channels toward the dural sinuses and jugular pathways. Collateral routes can redistribute outflow.','Superficial and deep cerebral veins have distinct collecting routes before their blood leaves the cranial cavity.','brainvein cerebral'],
 skin:['Head and neck perfusion','External carotid branches distribute oxygen and nutrients to extracranial tissues. Downstream changes in arteriolar resistance redistribute flow as metabolic demand and skin temperature change.','Branches of the external carotid form connections across neighboring territories.','vessel pressure'],
 coronary:['Myocardial perfusion','Oxygen extraction by myocardium is high at rest. Increasing myocardial work therefore requires a substantial increase in coronary flow through downstream vasodilation. Intramyocardial compression changes the pressure gradient during each beat.','The surface vessel supplies smaller branches entering the myocardial wall. Left ventricular perfusion is especially dependent on diastole.','heart coron'],
 cardiacvein:['Myocardial venous return','Myocardial capillaries empty into venules that join the epicardial venous network. Contraction can compress intramyocardial vessels and modulate venous outflow during the cardiac cycle.','Most large cardiac veins converge on the coronary sinus. The anterior cardiac veins have direct right atrial drainage.','cv coron'],
 pulmA:['Pulmonary perfusion','These branches deliver mixed venous blood to alveolar capillaries. Local alveolar hypoxia can increase downstream arteriolar resistance and redistribute flow toward better ventilated units.','More central arteries travel with the airway tree. Regional blood flow and ventilation together determine gas exchange.','lung pulmonary'],
 pulmV:['Pulmonary venous return','Blood from alveolar capillaries enters venules and returns toward the left atrium. Higher downstream atrial pressure can increase pulmonary venous and capillary hydrostatic pressure.','Many venous tributaries course between bronchopulmonary segments. The area drained by a vein need not correspond to the arterial supply of one segment.','pven lung'],
 armA:['Upper limb perfusion','When hand or forearm muscles work, local vasodilation increases regional flow. Arterial arches and joint anastomoses can distribute blood along more than one route, with capacity depending on their continuity and caliber.','Conduit arteries feed resistance vessels in skin, muscle, and other tissues of the upper limb.','vessel pressure'],
 armV:['Upper limb venous return','Superficial and deep drainage communicate through connecting veins. Pressure gradients and compression during muscle activity assist return toward the axillary and subclavian systems.','Paired deep veins often accompany an artery. Superficial veins follow separate subcutaneous courses.','systemic vessel'],
 legA:['Lower limb perfusion','Contraction increases the metabolic demand of skeletal muscle. Distal vasodilation increases flow from the major limb arteries during exercise, while surface arteries also supply skin.','The femoral, popliteal, tibial and foot vessels form successive parts of the delivery network.','vessel pressure'],
 legV:['Lower limb venous return','In the dependent limb, hydrostatic pressure increases with distance below the heart. Rhythmic muscle contraction compresses deep veins. Competent valves direct flow toward the heart and limit reverse flow between contractions.','Superficial veins connect to deep veins through perforating channels and named junctions.','systemic vessel'],
 portal:['Portal inflow','Venous effluent from digestive organs carries absorbed substances to hepatic sinusoids before blood returns to the systemic veins. Portal flow and hepatic arterial flow provide complementary liver inflow.','Blood in portal tributaries is downstream of a splanchnic capillary bed and upstream of the liver’s exchange bed.','vessel liver'],
 hepaticA:['Hepatic arterial inflow','The hepatic arterial tree distributes oxygenated systemic blood into the liver, including the peribiliary arterial supply. When portal flow decreases, the hepatic arterial buffer response can partly offset the change in perfusion.','Intrahepatic arterial and portal branches run together in portal tracts. Hepatic veins carry outflow toward the vena cava.','liver vessel'],
 hepaticV:['Hepatic venous outflow','Blood from hepatic arterial and portal venous inflow mixes across the sinusoidal bed. Central and collecting veins then direct it to hepatic veins and the inferior vena cava.','Changes in central venous pressure can be transmitted to hepatic venous outflow. These veins drain the liver after exchange.','liver vessel'],
 renalA:['Renal perfusion','The renal arterial tree feeds afferent arterioles and glomerular capillaries. Myogenic responses and tubuloglomerular feedback act mainly in small vessels to stabilize perfusion and filtration despite moderate pressure changes.','Glomerular blood exits through an efferent arteriole before reaching peritubular capillaries or vasa recta.','kidney vessel'],
 renalV:['Renal venous outflow','Peritubular capillaries and vasa recta drain through progressively larger veins to the renal vein. The renal arteriovenous pressure difference contributes to the gradient driving total renal flow.','The renal vein is downstream of both glomerular filtration and peritubular exchange.','kidney vessel'],
 gutA:['Splanchnic arterial supply','After a meal, secretion, absorption, and smooth-muscle activity increase local metabolic demand. Resistance changes within the gut wall help adjust regional flow. Venous blood then enters the portal system.','Mesenteric arcades and named arterial connections can link adjacent territories. Their caliber and completeness vary.','vessel pressure liver'],
 gutV:['Gastrointestinal venous drainage','Nutrients and other absorbed substances enter portal venous blood from the gut wall and reach hepatic sinusoids on the first pass. Pressure changes in the portal system influence outflow from its tributaries.','Venous drainage from the abdominal digestive tract is distinct from the systemic venous return of the body wall.','vessel liver'],
 thoraxV:['Thoracic venous return','Azygos-system channels collect body-wall venous blood and communicate with lumbar and caval pathways. Flow along these communications can change if a central venous pressure gradient changes.','The azygos arches over the right lung root to reach the superior vena cava. Left-sided tributaries can cross to the azygos.','azygos vessel'],
 centralV:['Central venous return','Venous capacitance and the gradient toward right atrial pressure influence return to the heart. During spontaneous inspiration, pressure changes in the chest and abdomen alter that gradient.','Venous flow depends on both upstream filling pressure and the downstream pressure at the right atrium.','vessel pressure'],
 artery:['Systemic arterial distribution','Pulsatile blood enters the named vessel from an upstream artery and reaches a downstream resistance network. Local arterioles adjust smooth-muscle tone to match blood flow to tissue demand.','For a fixed pressure difference, a rise in downstream resistance reduces flow. Delivery of oxygen also depends on arterial oxygen content.','vessel pressure'],
 vein:['Systemic venous drainage','Blood leaving a tissue exchange bed enters venules and collecting veins. Compliant venous walls allow considerable volume change with small pressure changes and contribute to the systemic blood reservoir.','The direction and volume of flow depend on pressure differences, vessel patency, and the available drainage pathways.','vessel pressure'],
};
window.vascularFamilies=families;
const unique={
 'aorta':'The coronary arteries originate from the aortic root. The arch then distributes flow toward the upper body, while the descending aorta continues toward the thorax and abdomen.',
 'brachiocephalic-trunk':'The first usual arch branch divides pressure and flow between the right carotid and subclavian pathways.',
 'common-carotid-artery':'The internal and external carotid arteries receive inflow from this vessel. Stretch of the sinus at the carotid bifurcation contributes to baroreceptor signaling.',
 'internal-carotid-artery':'The anterior and middle cerebral territories receive inflow from the internal carotid. Collateral pathways can change the balance between carotid and vertebrobasilar supply.',
 'external-carotid-artery':'Extracranial tissues draw blood through this system. Facial, maxillary, and superficial temporal territories have different patterns of demand from the cerebral circulation.',
 'facial-artery':'Its winding route accommodates motion of the lips and face. Anastomoses with adjacent cutaneous and contralateral facial branches can redistribute flow.',
 'maxillary-artery':'Branches deliver blood to deep facial structures, teeth, nasal cavity, and parts of the dura. Flow divides between those beds according to their resistance.',
 'superficial-temporal-artery':'The superficial terminal branch of the external carotid supplies the scalp. Its subcutaneous route permits its arterial pulse to be felt over the zygomatic arch.',
 'occipital-artery':'Posterior scalp and neck tissues receive supply from this external carotid branch. Neighboring scalp arteries communicate across territorial boundaries.',
 'vertebral-artery':'The paired vertebral arteries ascend to unite as the basilar artery. They also give off branches to the upper spinal cord, medulla, and cerebellum.',
 'basilar-artery':'Flow from the two vertebral arteries supplies pontine and cerebellar branches before dividing into the posterior cerebral arteries.',
 'anterior-cerebral-artery':'This artery perfuses much of the medial frontal and parietal cortex, including the lower-limb representation. The anterior communicating artery links right and left proximal circulations.',
 'anterior-communicating-artery':'A pressure difference between the two anterior cerebral arteries can drive collateral flow across this short connection. The direction depends on the prevailing gradient.',
 'middle-cerebral-artery':'Cortical branches reach much of the lateral cerebral hemisphere. Lenticulostriate perforators supply deep structures with less collateral redundancy than many cortical branches.',
 'posterior-cerebral-artery':'Cortical branches reach the occipital cortex and inferomedial temporal regions. Proximal perforators supply parts of the thalamus and midbrain.',
 'posterior-communicating-artery':'This connection between the internal carotid and posterior cerebral circulations can carry collateral flow in either direction. Its caliber determines how much it can carry.',
 'subclavian-artery':'The usual vertebral origin lies proximal to the limb supply. A pressure change upstream of that origin can alter the direction of vertebral flow.',
 'internal-thoracic-artery':'Its branches supply the anterior chest wall, including anterior intercostal spaces. Terminal branches continue toward the diaphragm and anterior abdominal wall.',
 'axillary-artery':'This continuation of the subclavian artery supplies the axilla and shoulder before continuing as the brachial artery. Scapular anastomoses can provide alternative inflow.',
 'brachial-artery':'This artery is the principal inflow conduit of the arm and usually divides near the elbow into the radial and ulnar arteries.',
 'deep-brachial-artery':'It supplies the posterior compartment of the arm and provides collateral branches around the elbow that connect with recurrent branches from the forearm.',
 'radial-artery':'It supplies the lateral forearm and commonly provides the dominant contribution to the deep palmar arch. Flow to the hand also depends on the ulnar circulation.',
 'ulnar-artery':'It supplies the medial forearm and usually provides most of the inflow to the superficial palmar arch.',
 'palmar-arches':'Superficial and deep arches distribute inflow into the palm and fingers. The completeness of each arch and relative radial and ulnar contributions vary.',
 'digital-arteries':'Digital flow supplies the fingers. Vasomotor changes in skin vessels can strongly alter fingertip flow during heat exchange.',
 'thoracic-aorta':'The descending thoracic segment supplies the posterior chest wall and thoracic viscera. It passes through the aortic hiatus to become the abdominal aorta.',
 'intercostal-arteries':'Posterior intercostal branches supply segmental chest-wall beds and communicate with anterior intercostal branches. The most superior spaces have different proximal origins.',
 'abdominal-aorta':'Renal, gastrointestinal, body-wall, reproductive, and lower-limb circulations share this inflow. Its bifurcation sends blood into the common iliac arteries.',
 'celiac-trunk':'Foregut derivatives receive arterial supply through the usual gastric, splenic, and common hepatic branches. Pancreaticoduodenal arcades provide a link with the superior mesenteric circulation.',
 'left-gastric-artery':'It supplies the lesser curvature and gives off esophageal branches. Its gastric branches connect with the right gastric artery along the lesser curvature.',
 'splenic-artery':'Branches supply splenic tissue, parts of the stomach, and the pancreas. The spleen filters systemic arterial blood and drains into the portal venous system.',
 'common-hepatic-artery':'The common hepatic artery gives rise to the gastroduodenal route and continues toward the liver as the proper hepatic artery in the usual arrangement.',
 'superior-mesenteric-artery':'Midgut perfusion includes most of the small intestine and proximal colon. A meal increases intestinal oxygen use and changes downstream arteriolar tone.',
 'inferior-mesenteric-artery':'This artery supplies the hindgut through left colic, sigmoid, and superior rectal branches. Colic anastomoses connect its territory with the superior mesenteric system.',
 'renal-artery':'Flow is delivered to a pair of serial microvascular beds separated by an efferent arteriole. Segmental renal branches have limited intersegmental collateral supply.',
 'gonadal-artery':'Paired gonadal arteries arise from the abdominal aorta and descend to the gonads. Their arterial origin reflects gonadal development high on the posterior abdominal wall.',
 'common-iliac-artery':'Each common iliac distributes aortic inflow between a pelvic route and a route continuing toward the lower limb.',
 'internal-iliac-artery':'Branches distribute blood to pelvic viscera, perineum, and gluteal tissues. The arrangement and origins of individual branches vary.',
 'external-iliac-artery':'Most flow continues to the limb as the femoral artery. Inferior epigastric and deep circumflex iliac branches also supply the lower abdominal wall.',
 'femoral-artery':'It supplies the thigh and continues through the adductor hiatus into the popliteal artery. The profunda femoris permits substantial distribution to thigh musculature.',
 'deep-femoral-artery':'Perforating branches supply thigh muscles and connect with neighboring arterial territories. These routes can contribute to collateral flow around a proximal obstruction.',
 'popliteal-artery':'Genicular branches supply the knee region. Distal branches then distribute blood to the leg and foot.',
 'anterior-tibial-artery':'It enters the anterior compartment of the leg and continues at the ankle as dorsalis pedis, linking anterior leg supply to the dorsum of the foot.',
 'posterior-tibial-artery':'It supplies the posterior leg and passes behind the medial malleolus toward the medial and lateral plantar arteries.',
 'fibular-artery':'Branches supply the lateral and posterior leg and contribute to connections around the ankle. Its origin and distal contributions can vary.',
 'dorsalis-pedis-artery':'This continuation of the anterior tibial artery supplies the dorsal foot. Its deep plantar branch connects to the plantar arterial arch.',
 'plantar-arteries':'Medial and lateral plantar pathways distribute blood to the sole. The lateral plantar artery contributes prominently to the deep plantar arch and forefoot inflow.',
 'superior-vena-cava':'The right and left brachiocephalic veins return upper-body blood through this vessel, while the azygos contributes venous drainage from the thoracic wall.',
 'brachiocephalic-vein':'The internal jugular and subclavian veins join on each side. The left brachiocephalic then crosses the superior mediastinum before joining the right-sided vein.',
 'internal-jugular-vein':'The sigmoid sinus continues into the internal jugular vein at the jugular foramen. Cerebral venous return can also redistribute through vertebral and other channels.',
 'dural-venous-sinuses':'These endothelium-lined channels in the dura carry blood toward the jugular outlets. Several also receive cerebrospinal fluid through arachnoid granulations.',
 'external-jugular-vein':'Superficial drainage from the scalp and face enters the subclavian system. Its course over sternocleidomastoid differs from that of the deeper internal jugular vein.',
 'facial-vein':'Facial venous return communicates with both superficial and deeper channels, including angular–ophthalmic connections and the deep facial route to the pterygoid plexus.',
 'subclavian-vein':'Venous return from the arm arrives through the axillary vein. At the venous angle it joins the internal jugular vein to form a brachiocephalic vein.',
 'axillary-vein':'The axillary vein collects deep and superficial upper-limb return, including cephalic inflow, before becoming the subclavian vein at the first rib.',
 'brachial-veins':'These deep veins accompany the brachial artery. Muscular movement and one-way valves aid return from the arm toward the axillary vein.',
 'deep-forearm-veins':'Radial and ulnar venae comitantes drain the deep forearm and communicate through cross-connections before feeding the brachial drainage route.',
 'cephalic-vein':'This superficial lateral route crosses the deltopectoral region and usually joins the axillary vein. Its connection with medial superficial drainage near the elbow is variable.',
 'basilic-vein':'The superficial medial pathway enters the deep fascia in the arm and joins deep veins in the transition to the axillary vein.',
 'median-cubital-vein':'This superficial connection commonly transfers blood between cephalic and basilic systems near the elbow. Superficial branching patterns differ among individuals.',
 'hand-venous-network':'Dorsal superficial channels drain toward cephalic and basilic routes. Their configuration varies and communicates with deeper venous networks.',
 'azygos-vein':'The azygos links lumbar and thoracic venous pathways and can carry collateral return when a caval route is obstructed.',
 'hemiazygos-vein':'Lower left posterior intercostal drainage travels toward the azygos by crossing the midline posterior to other mediastinal structures. The level of crossing varies.',
 'intercostal-veins':'Posterior intercostal veins connect the chest wall with the azygos and hemiazygos systems. Superior spaces can drain through superior intercostal or brachiocephalic routes.',
 'inferior-vena-cava':'The IVC collects venous return from below the diaphragm. Hepatic veins add post-sinusoidal outflow before it passes through the diaphragm to the right atrium.',
 'hepatic-veins':'These veins drain liver sinusoids through central and larger collecting veins. Hepatic venous pressure is influenced by right-sided cardiac pressure.',
 'hepatic-portal-vein':'The usual confluence of the superior mesenteric and splenic veins feeds the portal trunk. Its branches deliver nutrient-rich blood to liver sinusoids before systemic return.',
 'splenic-vein':'The splenic vein courses behind the pancreas and usually meets the superior mesenteric vein near the pancreatic neck. It also receives pancreatic and gastric tributaries.',
 'superior-mesenteric-vein':'It carries nutrient-rich venous effluent from much of the small intestine and proximal colon toward the portal vein.',
 'inferior-mesenteric-vein':'It drains the distal colon and superior rectum. Its terminal route often enters the splenic vein but can join the superior mesenteric vein or their confluence.',
 'renal-vein':'Renal venous blood returns directly toward the IVC. The longer left renal vein commonly receives left gonadal and suprarenal tributaries.',
 'gonadal-vein':'The right gonadal vein typically enters the IVC, while the left usually enters the left renal vein. Different outflow routes can expose each side to different upstream pressures.',
 'common-iliac-vein':'The internal and external iliac veins merge to drain the pelvis and limb toward the IVC. The left common iliac vein normally crosses under the right common iliac artery.',
 'internal-iliac-vein':'Communicating pelvic plexuses and gluteal tributaries drain toward this central pelvic route, then into a common iliac vein.',
 'external-iliac-vein':'Continuation of the femoral vein at the inguinal ligament carries lower-limb venous return toward the common iliac confluence.',
 'femoral-vein':'This deep venous conduit receives thigh drainage and the great saphenous route at the saphenofemoral junction in the groin.',
 'popliteal-vein':'Deep calf drainage converges behind the knee. The small saphenous vein commonly joins here, linking superficial and deep return.',
 'deep-leg-veins':'Anterior tibial, posterior tibial, and fibular veins accompany the corresponding arteries. Repeated calf-muscle contraction empties these deep channels proximally.',
 'great-saphenous-vein':'The superficial medial vein ascends from the foot and joins the femoral system at the groin. Perforating veins provide additional communication with deep return.',
 'small-saphenous-vein':'This superficial posterior calf vein usually joins the popliteal vein. The termination level and connections with the thigh vary.',
 'foot-venous-arch':'Superficial dorsal venous channels feed routes toward both saphenous veins. Plantar deep drainage also contributes to return during the foot and calf muscle pump.'
};
function family(name,layer,region='',classes=[]){
 const n=(name+' '+classes.join(' ')).toLowerCase(), ven=layer==='veins';
 if(/hepatic portal|portal vein|portal venous/.test(n))return 'portal';
 if(/pulmonary|lingular/.test(n)||region==='Thorax'&&/segmental|lobar/.test(n)&&!/hepatic|renal|interventricular/.test(n))return ven?'pulmV':'pulmA';
 if(/hepatic vein|hepatic venous/.test(n))return 'hepaticV';
 if(/hepatic artery|hepatic arterial/.test(n))return 'hepaticA';
 if(/cardiac vein|coronary sinus|vein of left ventricle|oblique vein of left atrium/.test(n))return 'cardiacvein';
 if(/coronary|diagonal branch|ventricular branch|right marginal artery|left marginal branch/.test(n))return 'coronary';
 if(/renal/.test(n)&&!/suprarenal/.test(n))return ven?'renalV':'renalA';
 if(/mesenteric|gastric|splenic|colic|colonic|ileal|ileocolic|gastroepiploic|gastro-epiploic|cecal|celiac|pancreatic|gastroduodenal|sigmoid vein|superior rectal|appendicular/.test(n))return ven?'gutV':'gutA';
 if(/dural|sagittal sinus|sigmoid sinus|cavernous sinus|petrosal sinus|transverse sinus|straight sinus/.test(n))return 'brainvein';
 if(/cerebr|cerebell|choroid|vertebral artery|basilar artery|communicating artery|internal carotid|pontine|thalam|occipital artery.*cerebral|pericallosal|callosomarginal|spinal artery/.test(n)||region==='Head & neck'&&!ven&&!/facial|external carotid|scalp|superficial temporal/.test(n))return 'cerebral';
 if(/aorta|aortic arch/.test(name.toLowerCase())&&!/branch/.test(name.toLowerCase()))return 'aorta';
 if(/azygos|hemiazygos|intercostal vein|ascending lumbar/.test(n))return 'thoraxV';
 if(/vena cava|brachiocephalic vein|jugular|common iliac vein|subclavian vein/.test(n))return 'centralV';
 if(/face|facial|external carotid|maxillary|superficial temporal|occipital artery/.test(n)&&!ven)return 'skin';
 if(region==='Upper limbs'||/axillary|brachial|subclavian|radial artery|radial vein|ulnar|palmar|hand|cephalic vein|basilic|cubital|deep forearm|digital arter/.test(n))return ven?'armV':'armA';
 if(region==='Lower limbs'||/femoral|saphenous|popliteal|tibial|fibular|pedis|plantar|foot|deep leg/.test(n))return ven?'legV':'legA';
 return ven?'vein':'artery';
}
window.resolveVascularFamily=family;
const V={};
for(const e of vesselStructures){
 const f=e.id==='systemic-vessels'?families.pump:families[family(e.name,e.layer)];
 V[e.id]={course:e.location,physiology:[unique[e.id]||e.role,f[1]],relationship:[e.role,f[2]],variation:'',sources:f[3].split(' ').map(k=>R[k])};
}
window.vascularDossiers=V;
})();
